{
    const char *name;
    unsigned int arity;
    void *func;
} function_table[] = {
    {"pow", 2, powf},     {"sin", 1, sinf},   {"cos", 1, cosf},     {"tan", 1, tanf},   {"abs", 1, fabsf},
    {"sqrt", 1, sqrtf},   {"log", 1, logf},   {"log10", 1, log10f}, {"exp", 1, expf},   {"floor", 1, floorf},
    {"round", 1, roundf}, {"ceil", 1, ceilf}, {"asin", 1, asinf},   {"acos", 1, acosf}, {"atan", 1, atanf},
    {"atan2", 2, atan2f}, {"sinh", 1, sinhf}, {"cosh", 1, coshf},   {"tanh", 1, tanhf}, {"logb", 1, logbf},
    {"exp2", 1, exp2f},   {"log2", 1, log2f}, {"hypot", 2, hypotf}, {"cbrt", 1, cbrtf}, {"trunc", 1, truncf},
    {"min", 2, minf},     {"max", 2, maxf},   {"pi", 0, pif},
