structs.token_t:
typedef struct _token
{
    enum
    {
        TOK_FLOAT,
        TOK_INT,
        TOK_OP,
        TOK_OPEN_PAREN,
        TOK_CLOSE_PAREN,
        TOK_VAR,
        TOK_OPEN_SQUARE,
        TOK_CLOSE_SQUARE,
        TOK_OPEN_CURLY,
        TOK_CLOSE_CURLY,
        TOK_FUNC,
        TOK_COMMA,
        TOK_END,
        TOK_TOFLOAT,
        TOK_TOINT32,
    } type;
    union {
        float f;
        int i;
        char var;
        char op;
        expr_func_t func;
    };
} token_t;

structs.exprnode:
typedef struct _exprnode
{
    token_t tok;
    int is_float;
    int history_index;
    int vector_index;
    struct _exprnode *next;
} *exprnode;

structs._mapper_expr:
struct _mapper_expr
{
    exprnode node;
    int vector_size;
    int history_size;
    int history_pos;
    mapper_signal_value_t *input_history;
    mapper_signal_value_t *output_history;
}

structs.stack_obj_t:
typedef struct _stack_obj
{
    union {
        state_t state;
        exprnode node;
    };
    enum
    {
        ST_STATE,
        ST_NODE,
    } type;
} stack_obj_t;

unions.mapper_signal_value_t:
typedef union _mapper_signal_value_t {
    float f;
    int i32;
} mapper_signal_value_t;

functions.minf:
static float minf(float x, float y)
{
    if (y < x)
        return y;
    else
        return x;
}

functions.maxf:
static float maxf(float x, float y)
{
    if (y > x)
        return y;
    else
        return x;
}

functions.function_lookup:
static expr_func_t function_lookup(const char *s, int len)
{
    int i;
    for (i = 0; i < N_FUNCS; i++)
    {
        if (strncmp(s, function_table[i].name, len) == 0)
            return i;
    }
    return FUNC_UNKNOWN;
}

functions.expr_lex:
static int expr_lex(const char **str, token_t *tok)
{
    int n = 0;
    char c = **str;
    const char *s;
    int integer_found = 0;
    if (c == 0)
    {
        tok->type = TOK_END;
        return 0;
    }
again:
    if (((*__ctype_b_loc())[(int)((c))] & (unsigned short int)_ISdigit))
    {
        s = *str;
        do
        {
            c = (*(++*str));
        } while (c && ((*__ctype_b_loc())[(int)((c))] & (unsigned short int)_ISdigit));
        n = atoi(s);
        integer_found = 1;
        if (c != '.')
        {
            tok->i = n;
            tok->type = TOK_INT;
            return 0;
        }
    }
    switch (c)
    {
    case '.':
        s = *str;
        c = (*(++*str));
        if (!((*__ctype_b_loc())[(int)((c))] & (unsigned short int)_ISdigit) && integer_found)
        {
            tok->type = TOK_FLOAT;
            tok->f = (float)n;
            return 0;
        }
        if (!((*__ctype_b_loc())[(int)((c))] & (unsigned short int)_ISdigit))
            break;
        do
        {
            c = (*(++*str));
        } while (c && ((*__ctype_b_loc())[(int)((c))] & (unsigned short int)_ISdigit));
        tok->f = (float)n + atof(s);
        tok->type = TOK_FLOAT;
        return 0;
    case '+':
    case '-':
    case '/':
    case '*':
    case '=':
        tok->type = TOK_OP;
        tok->op = c;
        ++*str;
        return 0;
    case '(':
        tok->type = TOK_OPEN_PAREN;
        ++*str;
        return 0;
    case ')':
        tok->type = TOK_CLOSE_PAREN;
        ++*str;
        return 0;
    case 'x':
    case 'y':
        tok->type = TOK_VAR;
        tok->var = c;
        ++*str;
        return 0;
    case '[':
        tok->type = TOK_OPEN_SQUARE;
        ++*str;
        return 0;
    case ']':
        tok->type = TOK_CLOSE_SQUARE;
        ++*str;
        return 0;
    case '{':
        tok->type = TOK_OPEN_CURLY;
        ++*str;
        return 0;
    case '}':
        tok->type = TOK_CLOSE_CURLY;
        ++*str;
        return 0;
    case ' ':
    case '\t':
    case '\r':
    case '\n':
        c = (*(++*str));
        goto again;
    case ',':
        tok->type = TOK_COMMA;
        ++*str;
        return 0;
    default:
        if (!((*__ctype_b_loc())[(int)((c))] & (unsigned short int)_ISalpha))
        {
            printf("unknown character '%c' in lexer\n", c);
            break;
        }
        s = *str;
        while (c && (((*__ctype_b_loc())[(int)((c))] & (unsigned short int)_ISalpha) ||
                     ((*__ctype_b_loc())[(int)((c))] & (unsigned short int)_ISdigit)))
            c = (*(++*str));
        tok->type = TOK_FUNC;
        tok->func = function_lookup(s, *str - s);
        return 0;
    }
    return 1;
}

functions.exprnode_new:
static exprnode exprnode_new(token_t *tok, int is_float)
{
    exprnode t = (exprnode)malloc(sizeof(struct _exprnode));
    t->tok = *tok;
    t->is_float = is_float;
    t->history_index = 0;
    t->vector_index = 0;
    t->next = 0;
    return t;
}

functions.exprnode_free:
static void exprnode_free(exprnode e)
{
    while (e)
    {
        exprnode tmp = e;
        e = e->next;
        free(tmp);
    }
}

functions.mapper_expr_free:
void mapper_expr_free(mapper_expr expr)
{
    exprnode_free(expr->node);
    free(expr->input_history);
    free(expr->output_history);
    free(expr);
}

functions.collapse_expr_to_left:
static void collapse_expr_to_left(exprnode *plhs, exprnode rhs, int constant_folding)
{
    int refvar = 0;
    int is_float = 0;
    exprnode rhs_last = rhs;
    if (rhs->tok.type == TOK_VAR)
        refvar = 1;
    while (rhs_last->next)
    {
        if (rhs_last->tok.type == TOK_VAR)
            refvar = 1;
        rhs_last = rhs_last->next;
    }
    exprnode *plhs_last = plhs;
    if ((*plhs_last)->tok.type == TOK_VAR)
        refvar = 1;
    while ((*plhs_last)->next)
    {
        if ((*plhs_last)->tok.type == TOK_VAR)
            refvar = 1;
        plhs_last = &(*plhs_last)->next;
    }
    token_t coerce;
    coerce.type = TOK_TOFLOAT;
    is_float = (*plhs_last)->is_float || rhs_last->is_float;
    if ((*plhs_last)->is_float && !rhs_last->is_float)
    {
        rhs_last = rhs_last->next = exprnode_new(&coerce, 1);
    }
    else if (!(*plhs_last)->is_float && rhs_last->is_float)
    {
        exprnode e = exprnode_new(&coerce, 1);
        e->next = (*plhs_last);
        (*plhs_last) = e;
        plhs_last = &e->next;
        e->next->is_float = 1;
    }
    rhs_last->next = (*plhs_last);
    (*plhs_last) = rhs;
    if (constant_folding && !refvar)
    {
        struct _mapper_expr e;
        e.node = *plhs;
        mapper_signal_value_t v;
        mapper_expr_evaluate(&e, 0, &v);
        exprnode_free((*plhs)->next);
        (*plhs)->next = 0;
        (*plhs)->is_float = is_float;
        if (is_float)
        {
            (*plhs)->tok.type = TOK_FLOAT;
            (*plhs)->tok.f = v.f;
        }
        else
        {
            (*plhs)->tok.type = TOK_INT;
            (*plhs)->tok.i = v.i32;
        }
    }
}

functions.mapper_expr_new_from_string:
mapper_expr mapper_expr_new_from_string(const char *str, int input_is_float, int output_is_float, int vector_size)
{
    const char *s = str;
    if (!str)
        return 0;
    stack_obj_t stack[256];
    int top = -1;
    exprnode result = 0;
    const char *error_message = 0;
    token_t tok;
    int i, next_token = 1;
    int var_allowed = 1;
    float oldest_samps = 0;
    {
        top++;
        stack[top].state = EXPR;
        stack[top].type = ST_STATE;
    };
    {
        top++;
        stack[top].state = YEQUAL_EQ;
        stack[top].type = ST_STATE;
    };
    {
        top++;
        stack[top].state = YEQUAL_Y;
        stack[top].type = ST_STATE;
    };
    while (top >= 0)
    {
        if (next_token && expr_lex(&s, &tok))
        {
            {
                error_message = "Error in lexical analysis.";
                result = 0;
                goto done;
            };
        }
        next_token = 0;
        if (stack[top].type == ST_NODE)
        {
            if (top == 0)
            {
                result = stack[top].node;
                goto done;
            };
            if (stack[top - 1].type == ST_STATE)
            {
                if (top >= 2 && stack[top - 2].type == ST_NODE)
                {
                    if (stack[top - 1].type == ST_STATE &&
                        (stack[top - 1].state == EXPR_RIGHT || stack[top - 1].state == TERM_RIGHT ||
                         stack[top - 1].state == CLOSE_PAREN))
                    {
                        collapse_expr_to_left(&stack[top - 2].node, stack[top].node, 1);
                        (top--);
                    }
                    else if (stack[top - 1].type == ST_STATE && stack[top - 1].state == CLOSE_HISTINDEX)
                    {
                        {};
                        {};
                        if (stack[top].node->tok.type == TOK_FLOAT)
                            stack[top - 2].node->history_index = (int)stack[top].node->tok.f;
                        else
                            stack[top - 2].node->history_index = stack[top].node->tok.i;
                        if (oldest_samps > stack[top - 2].node->history_index)
                            oldest_samps = stack[top - 2].node->history_index;
                        exprnode_free(stack[top].node);
                        (top--);
                    }
                    else if (stack[top - 1].type == ST_STATE && stack[top - 1].state == CLOSE_VECTINDEX)
                    {
                        {};
                        {};
                        if (stack[top].node->tok.type == TOK_FLOAT)
                            stack[top - 2].node->vector_index = (int)stack[top].node->tok.f;
                        else
                            stack[top - 2].node->vector_index = stack[top].node->tok.i;
                        if (stack[top - 2].node->vector_index > 0)
                        {
                            {
                                error_message = "Vector indexing not yet implemented.";
                                result = 0;
                                goto done;
                            };
                        }
                        if (stack[top - 2].node->vector_index < 0 || stack[top - 2].node->vector_index >= vector_size)
                        {
                            {
                                error_message = "Vector index outside input size.";
                                result = 0;
                                goto done;
                            };
                        }
                        exprnode_free(stack[top].node);
                        (top--);
                    }
                }
                else
                {
                    stack_obj_t tmp = stack[top - 1];
                    stack[top - 1] = stack[top];
                    stack[top] = tmp;
                }
            }
            continue;
        }
        switch (stack[top].state)
        {
        case YEQUAL_Y:
            if (tok.type == TOK_VAR && tok.var == 'y')
                (top--);
            else
            {
                {
                    error_message = "Error in y= prefix.";
                    result = 0;
                    goto done;
                };
            }
            next_token = 1;
            break;
        case YEQUAL_EQ:
            if (tok.type == TOK_OP && tok.op == '=')
            {
                (top--);
            }
            else
            {
                {
                    {
                        error_message = "Error in y= prefix.";
                        result = 0;
                        goto done;
                    };
                }
            }
            next_token = 1;
            break;
        case EXPR:
            (top--);
            {
                top++;
                stack[top].state = EXPR_RIGHT;
                stack[top].type = ST_STATE;
            };
            {
                top++;
                stack[top].state = TERM;
                stack[top].type = ST_STATE;
            };
            break;
        case EXPR_RIGHT:
            if (tok.type == TOK_OP)
            {
                (top--);
                if (tok.op == '+' || tok.op == '-')
                {
                    if (stack[top].type == ST_NODE)
                    {
                        exprnode e = stack[top].node;
                        while (e->next)
                            e = e->next;
                        e->next = exprnode_new(&tok, 0);
                        e->next->is_float = e->is_float;
                    };
                    {
                        top++;
                        stack[top].state = EXPR;
                        stack[top].type = ST_STATE;
                    };
                    next_token = 1;
                }
            }
            else
                (top--);
            break;
        case TERM:
            (top--);
            {
                top++;
                stack[top].state = TERM_RIGHT;
                stack[top].type = ST_STATE;
            };
            {
                top++;
                stack[top].state = VALUE;
                stack[top].type = ST_STATE;
            };
            break;
        case TERM_RIGHT:
            if (tok.type == TOK_OP)
            {
                (top--);
                if (tok.op == '*' || tok.op == '/')
                {
                    if (stack[top].type == ST_NODE)
                    {
                        exprnode e = stack[top].node;
                        while (e->next)
                            e = e->next;
                        e->next = exprnode_new(&tok, 0);
                        e->next->is_float = e->is_float;
                    };
                    {
                        top++;
                        stack[top].state = TERM;
                        stack[top].type = ST_STATE;
                    };
                    next_token = 1;
                }
            }
            else
                (top--);
            break;
        case VALUE:
            if (tok.type == TOK_INT)
            {
                (top--);
                {
                    top++;
                    stack[top].node = exprnode_new(&tok, 0);
                    stack[top].type = ST_NODE;
                };
                next_token = 1;
            }
            else if (tok.type == TOK_FLOAT)
            {
                (top--);
                {
                    top++;
                    stack[top].node = exprnode_new(&tok, 1);
                    stack[top].type = ST_NODE;
                };
                next_token = 1;
            }
            else if (tok.type == TOK_VAR)
            {
                if (var_allowed)
                {
                    (top--);
                    {
                        top++;
                        stack[top].node = exprnode_new(&tok, input_is_float);
                        stack[top].type = ST_NODE;
                    };
                    {
                        top++;
                        stack[top].state = VAR_RIGHT;
                        stack[top].type = ST_STATE;
                    };
                    next_token = 1;
                }
                else
                {
                    {
                        error_message = "Unexpected variable reference.";
                        result = 0;
                        goto done;
                    };
                }
            }
            else if (tok.type == TOK_OPEN_PAREN)
            {
                (top--);
                {
                    top++;
                    stack[top].state = CLOSE_PAREN;
                    stack[top].type = ST_STATE;
                };
                {
                    top++;
                    stack[top].state = EXPR;
                    stack[top].type = ST_STATE;
                };
                next_token = 1;
            }
            else if (tok.type == TOK_FUNC)
            {
                (top--);
                if (tok.func == FUNC_UNKNOWN)
                {
                    {
                        error_message = "Unknown function.";
                        result = 0;
                        goto done;
                    };
                }
                else
                {
                    {
                        top++;
                        stack[top].node = exprnode_new(&tok, 1);
                        stack[top].type = ST_NODE;
                    };
                    int arity = function_table[tok.func].arity;
                    if (arity > 0)
                    {
                        {
                            top++;
                            stack[top].state = CLOSE_PAREN;
                            stack[top].type = ST_STATE;
                        };
                        {
                            top++;
                            stack[top].state = EXPR;
                            stack[top].type = ST_STATE;
                        };
                        for (i = 1; i < arity; i++)
                        {
                            {
                                top++;
                                stack[top].state = COMMA;
                                stack[top].type = ST_STATE;
                            };
                            {
                                top++;
                                stack[top].state = EXPR;
                                stack[top].type = ST_STATE;
                            };
                        }
                        {
                            top++;
                            stack[top].state = OPEN_PAREN;
                            stack[top].type = ST_STATE;
                        };
                    }
                    next_token = 1;
                }
            }
            else if (tok.type == TOK_OP && tok.op == '-')
            {
                (top--);
                {
                    top++;
                    stack[top].state = NEGATE;
                    stack[top].type = ST_STATE;
                };
                {
                    top++;
                    stack[top].state = VALUE;
                    stack[top].type = ST_STATE;
                };
                next_token = 1;
            }
            else
            {
                {
                    error_message = "Expected value.";
                    result = 0;
                    goto done;
                };
            }
            break;
        case NEGATE:
            (top--);
            if (stack[top].type == ST_NODE)
            {
                token_t t;
                t.type = TOK_INT;
                t.i = 0;
                exprnode e = exprnode_new(&t, 0);
                t.type = TOK_OP;
                t.op = '-';
                e->next = exprnode_new(&t, 0);
                collapse_expr_to_left(&e, stack[top].node, 1);
                stack[top].node = e;
            }
            else
            {
                {
                    error_message = "Expected to negate an expression.";
                    result = 0;
                    goto done;
                };
            }
            break;
        case VAR_RIGHT:
            if (tok.type == TOK_OPEN_SQUARE)
            {
                (top--);
                {
                    top++;
                    stack[top].state = VAR_VECTINDEX;
                    stack[top].type = ST_STATE;
                };
            }
            else if (tok.type == TOK_OPEN_CURLY)
            {
                (top--);
                {
                    top++;
                    stack[top].state = VAR_HISTINDEX;
                    stack[top].type = ST_STATE;
                };
            }
            else
                (top--);
            break;
        case VAR_VECTINDEX:
            (top--);
            if (tok.type == TOK_OPEN_SQUARE)
            {
                var_allowed = 0;
                {
                    top++;
                    stack[top].state = CLOSE_VECTINDEX;
                    stack[top].type = ST_STATE;
                };
                {
                    top++;
                    stack[top].state = EXPR;
                    stack[top].type = ST_STATE;
                };
                next_token = 1;
            }
            break;
        case VAR_HISTINDEX:
            (top--);
            if (tok.type == TOK_OPEN_CURLY)
            {
                var_allowed = 0;
                {
                    top++;
                    stack[top].state = CLOSE_HISTINDEX;
                    stack[top].type = ST_STATE;
                };
                {
                    top++;
                    stack[top].state = EXPR;
                    stack[top].type = ST_STATE;
                };
                next_token = 1;
            }
            break;
        case CLOSE_VECTINDEX:
            if (tok.type == TOK_CLOSE_SQUARE)
            {
                var_allowed = 1;
                (top--);
                {
                    top++;
                    stack[top].state = VAR_HISTINDEX;
                    stack[top].type = ST_STATE;
                };
                next_token = 1;
            }
            else
            {
                {
                    error_message = "Expected ']'.";
                    result = 0;
                    goto done;
                };
            }
            break;
        case CLOSE_HISTINDEX:
            if (tok.type == TOK_CLOSE_CURLY)
            {
                var_allowed = 1;
                (top--);
                {
                    top++;
                    stack[top].state = VAR_VECTINDEX;
                    stack[top].type = ST_STATE;
                };
                next_token = 1;
            }
            else
            {
                {
                    error_message = "Expected '}'.";
                    result = 0;
                    goto done;
                };
            }
            break;
        case CLOSE_PAREN:
            if (tok.type == TOK_CLOSE_PAREN)
            {
                (top--);
                next_token = 1;
                break;
            }
            else
            {
                {
                    error_message = "Expected ')'.";
                    result = 0;
                    goto done;
                };
            }
            break;
        case COMMA:
            if (tok.type == TOK_COMMA)
            {
                (top--);
                for (i = top - 1; i >= 0 && stack[i].type != ST_NODE; --i)
                {
                };
                if (i >= 0)
                {
                    collapse_expr_to_left(&stack[i].node, stack[top].node, 0);
                    (top--);
                }
                next_token = 1;
            }
            else
            {
                {
                    error_message = "Expected ','.";
                    result = 0;
                    goto done;
                };
            }
            break;
        case OPEN_PAREN:
            if (tok.type == TOK_OPEN_PAREN)
            {
                (top--);
                next_token = 1;
            }
            else
            {
                {
                    error_message = "Expected '('.";
                    result = 0;
                    goto done;
                };
            }
            break;
        case END:
            if (tok.type == TOK_END)
            {
                (top--);
                break;
            }
            else
            {
                {
                    error_message = "Expected END.";
                    result = 0;
                    goto done;
                };
            }
        default: {
            error_message = "Unexpected parser state.";
            result = 0;
            goto done;
        };
        break;
        }
    }
done:
    if (!result)
    {
        if (error_message)
            printf("%s\n", error_message);
        goto cleanup;
    }
    if (oldest_samps < -100)
    {
        {};
        goto cleanup;
    }
    exprnode e = result;
    while (e->next)
        e = e->next;
    if (e->is_float && !output_is_float)
    {
        token_t coerce;
        coerce.type = TOK_TOINT32;
        e->next = exprnode_new(&coerce, 0);
        e->next->is_float = 0;
    }
    else if (!e->is_float && output_is_float)
    {
        token_t coerce;
        coerce.type = TOK_TOFLOAT;
        e->next = exprnode_new(&coerce, 0);
        e->next->is_float = 1;
    }
    if (vector_size > 1)
    {
        e = result;
        while (e)
        {
            if (e->tok.type == TOK_VAR && e->vector_index > 0)
            {
                {};
                goto cleanup;
            }
            e = e->next;
        }
    }
    mapper_expr expr = malloc(sizeof(struct _mapper_expr));
    expr->node = result;
    expr->vector_size = vector_size;
    expr->history_size = (int)ceilf(-oldest_samps) + 1;
    expr->history_pos = -1;
    expr->input_history = calloc(1, sizeof(mapper_signal_value_t) * vector_size * expr->history_size);
    expr->output_history = calloc(1, sizeof(mapper_signal_value_t) * expr->history_size);
    return expr;
cleanup:
    for (i = 0; i < top; i++)
    {
        if (stack[i].type == ST_NODE)
            exprnode_free(stack[i].node);
    }
    return 0;
}

functions.mapper_expr_evaluate:
int mapper_expr_evaluate(mapper_expr expr, void *input_vector, void *output_vector)
{
    mapper_signal_value_t stack[256];
    mapper_signal_value_t left, right;
    int top = -1;
    exprnode node = expr->node;
    if (input_vector)
    {
        expr->history_pos = (expr->history_pos + 1) % expr->history_size;
        memcpy(&expr->input_history[expr->history_pos * expr->vector_size], input_vector,
               expr->vector_size * sizeof(mapper_signal_value_t));
    }
    while (node)
    {
        switch (node->tok.type)
        {
        case TOK_INT:
            stack[++top].i32 = node->tok.i;
            break;
        case TOK_FLOAT:
            stack[++top].f = node->tok.f;
            break;
        case TOK_VAR: {
        };
            {
                int idx = ((node->history_index + expr->history_pos + expr->history_size) % expr->history_size);
                switch (node->tok.var)
                {
                case 'x':
                    idx = idx * expr->vector_size + node->vector_index;
                    stack[++top] = expr->input_history[idx];
                    break;
                case 'y':
                    stack[++top] = expr->output_history[idx];
                    break;
                default:
                    goto error;
                }
            }
            break;
        case TOK_TOFLOAT:
            stack[top].f = (float)stack[top].i32;
            break;
        case TOK_TOINT32:
            stack[top].i32 = (int)stack[top].f;
            break;
        case TOK_OP:
            right = stack[top--];
            left = stack[top--];
            if (node->is_float)
            {
                trace_eval("%f %c %f = ", left.f, node->tok.op, right.f);
                switch (node->tok.op)
                {
                case '+':
                    stack[++top].f = left.f + right.f;
                    break;
                case '-':
                    stack[++top].f = left.f - right.f;
                    break;
                case '*':
                    stack[++top].f = left.f * right.f;
                    break;
                case '/':
                    stack[++top].f = left.f / right.f;
                    break;
                default:
                    goto error;
                }
                trace_eval("%f\n", stack[top].f);
            }
            else
            {
                trace_eval("%d %c %d = ", left.i32, node->tok.op, right.i32);
                switch (node->tok.op)
                {
                case '+':
                    stack[++top].i32 = left.i32 + right.i32;
                    break;
                case '-':
                    stack[++top].i32 = left.i32 - right.i32;
                    break;
                case '*':
                    stack[++top].i32 = left.i32 * right.i32;
                    break;
                case '/':
                    stack[++top].i32 = left.i32 / right.i32;
                    break;
                default:
                    goto error;
                }
                trace_eval("%d\n", stack[top].i32);
            }
            break;
        case TOK_FUNC:
            switch (function_table[node->tok.func].arity)
            {
            case 0:
                stack[++top].f = ((func_float_arity0 *)function_table[node->tok.func].func)();
                trace_eval("%s = %f\n", function_table[node->tok.func].name, stack[top].f);
                break;
            case 1:
                right = stack[top--];
                trace_eval("%s(%f) = ", function_table[node->tok.func].name, right.f);
                right.f = ((func_float_arity1 *)function_table[node->tok.func].func)(right.f);
                trace_eval("%f\n", right.f);
                stack[++top].f = right.f;
                break;
            case 2:
                right = stack[top--];
                left = stack[top--];
                trace_eval("%s(%f,%f) = ", function_table[node->tok.func].name, left.f, right.f);
                right.f = ((func_float_arity2 *)function_table[node->tok.func].func)(left.f, right.f);
                trace_eval("%f\n", right.f);
                stack[++top].f = right.f;
                break;
            default:
                goto error;
            }
            break;
        default:
            goto error;
        }
        node = node->next;
    }
    if (input_vector)
        expr->output_history[expr->history_pos] = stack[0];
    *(mapper_signal_value_t *)output_vector = stack[0];
    return 0;
error: {
};
    stack[0].i32 = 0;
    *(mapper_signal_value_t *)output_vector = stack[0];
    return 1;
}
